 // Values belong to their full clock hour, including a partial first interval.
 const hourly=[...rows.filter((r,i)=>i===0||Math.floor(Date.parse(r.time)/3600000)!==Math.floor(Date.parse(rows[i-1].time)/3600000)).map(r=>({...r,time:new Date(Math.floor(Date.parse(r.time)/3600000)*3600000).toISOString()})),endpoint];
