 if(exportPeriods){for(let [key,color,height] of [['charging_window','#a9cce3',h-top-b],['peak_window','#f1ddb9',h-top-b],['battery_export_kw','#c28b3c',5]]){let first=null;for(let i=0;i<=rows.length;i++){let on=i<rows.length&&Number(rows[i][key])>0;if(on&&first===null)first=i;if(!on&&first!==null){let right=i<rows.length?eventX(i):w-r;out+=`<rect data-period="${key}" x="${eventX(first)}" y="${top}" width="${Math.max(1,right-eventX(first))}" height="${height}" fill="${color}" opacity="${height===5?'.9':'.25'}"/>`;first=null;}}}}
 if(threshold!=null)out+=`<line x1="${l}" x2="${w-r}" y1="${y(threshold)}" y2="${y(threshold)}" style="stroke:#b78a52;stroke-dasharray:5 4"/><text x="${w-r-4}" y="${y(threshold)-5}" text-anchor="end">Minimum ${threshold}%</text>`;
