function legend(items){return `<div class="legend">${items.map(([label,color])=>`<span><i style="background:${color}"></i>${esc(label)}</span>`).join('')}</div>`;}
function jobLabel(label){if(label.startsWith('Calibrate ')){const id=label.slice('Calibrate '.length);return id==='solar-__combined'?'Training combined solar production':'Training: '+modelName(id);}return label;}
function jobsHTML(){return (state.jobs||[]).filter(j=>j.status==='running'||j.status==='failed'&&Date.now()-new Date(j.finished_at)<600000).map(j=>`<article class="panel job ${j.status==='failed'?'warning':''}"><strong>${esc(jobLabel(j.label))}</strong><p>${esc(j.message)}</p>${j.status==='running'?'<div class="progress-track"><span></span></div>':''}</article>`).join('');}
function forecastTotals(rows,horizon,metrics=[['Forecast home consumption','load_point'],['Forecast solar production','solar_point']]){
 const horizons=[];for(let hours=24;hours<horizon;hours+=24)horizons.push(hours);horizons.push(horizon);
 const start=Date.parse(rows[0]?.time);
 const total=(key,hours)=>rows.reduce((sum,row)=>{
  const duration=Math.max(0,Math.min(row.hours,hours-(Date.parse(row.time)-start)/3600000));
  return sum+row[key]*duration;
 },0);
 return `<div class="chart-summary forecast-totals"><table aria-label="Cumulative forecast energy totals"><thead><tr><th scope="col">Forecast totals</th>${horizons.map(hours=>`<th scope="col">Next ${hours} hours</th>`).join('')}</tr></thead><tbody>${metrics.map(([label,key])=>`<tr><th scope="row">${esc(label.split(' (')[0])}${label.includes(' (')?`<small>${esc(label.split(' (')[1].slice(0,-1))}</small>`:''}</th>${horizons.map(hours=>`<td>${rows.length?fmt(total(key,hours)):'—'} <span class="energy-unit">kWh</span></td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
}
